let timer,container,callbacks,room,network,busy=false,signature='',generation=0;
let code=new URLSearchParams(location.search).get('room')||(()=>{try{return sessionStorage.getItem('lunchrun3-last-room')||'';}catch{return '';}})(),key='',draft=new Set(),drawTarget=null,drawStarted=false;
const outsideControls=new Map();
const appBase=['/game','/games'].find(prefix=>location.pathname===prefix||location.pathname.startsWith(prefix+'/'))||'';
function lockSharedFilters(active){document.body.classList.toggle('room-connected',active);if(active){for(const e of document.querySelectorAll('#filters-form input,#filters-form select,#category-options button,#location,#reset-filters,#quick-pick')){if(!outsideControls.has(e))outsideControls.set(e,e.disabled);e.disabled=true;}}else{for(const [e,disabled] of outsideControls)if(e.isConnected)e.disabled=disabled;outsideControls.clear();}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getToken=c=>{try{return sessionStorage.getItem('lunchrun3-room-'+c)||'';}catch{return '';}};
const saveToken=(c,k)=>{try{sessionStorage.setItem('lunchrun3-room-'+c,k);sessionStorage.setItem('lunchrun3-last-room',c);}catch{}};
async function api(url,data){const gen=generation;const res=await fetch(appBase+url,{method:data?'POST':'GET',signal:AbortSignal.timeout(15000),headers:{'Content-Type':'application/json',...(key?{Authorization:'Bearer '+key}:{})},...(data?{body:JSON.stringify(data)}:{})});const value=await res.json();if(gen!==generation)throw new Error('이전 모임 요청이 취소되었습니다.');if(!res.ok)throw new Error(value.error||'서버 연결을 확인해주세요.');return value;}
function notice(text){const e=container?.querySelector('.room-message');if(e){e.textContent=text;e.hidden=false;}}
export function closeRoomFlow(){generation++;clearTimeout(timer);lockSharedFilters(false);document.documentElement.classList.remove('room-invite-page');container=null;signature='';}
export async function mountRoomFlow(target,options){if(container===target&&target.querySelector('.room-app')){callbacks=options;if(!room){const chips=target.querySelector('.room-entry-card .room-filter-chips');if(chips)chips.innerHTML=filterChips(options.getFilters());}return;}closeRoomFlow();if(/^\d{6}$/.test(new URLSearchParams(location.search).get('room')||''))document.documentElement.classList.add('room-invite-page');container=target;callbacks=options;busy=false;container.innerHTML='<div class="room-app"><p>모임방을 준비하고 있어요…</p></div>';const mountGeneration=generation;try{network=await api('/api/network');if(mountGeneration!==generation||!container)return;if(code&&(key=getToken(code))){room=await api('/api/rooms/'+code);draft=new Set(room.me.choices);signature='';callbacks.onContext?.(room.filters,room.total,room.menus);lockSharedFilters(true);render();poll();}else renderEntry();}catch(e){renderEntry();notice(e.message);}}
function intro(step){return `<div class="room-top"><span class="room-eyebrow">TOGETHER, WE FIND OUR TASTE</span><h2>함께 고르는 오늘의 점심</h2><p>QR로 모이고, 각자 고르고, 모두의 취향을 찾아요.</p><div class="room-steps">${['모임방','메뉴 선택','공통 결과'].map((t,i)=>`<span class="${step===i?'active':''}"><b>0${i+1}</b> ${t}</span>`).join('')}</div></div><p class="room-message" role="status" hidden></p>`;}
function renderEntry(){if(!container)return;lockSharedFilters(false);room=null;signature='';if(/^\d{6}$/.test(code)&&new URLSearchParams(location.search).get('room')===code){renderInviteEntry();return;}document.documentElement.classList.remove('room-invite-page');container.innerHTML=`<div class="room-app">${intro(0)}<div class="room-entry-grid"><section class="room-entry-card"><span class="room-eyebrow">CREATE A ROOM</span><h3>우리의 교집합</h3><p>현재 점심 조건으로 방을 만들고 친구를 초대해요.</p><label>방장 닉네임<input id="room-host-name" class="field" maxlength="20" placeholder="예: 현서"></label><label>모임 이름<input id="room-title" class="field" maxlength="40" value="오늘의 점심 모임"></label><div class="room-filter-chips">${filterChips(callbacks.getFilters())}</div><button class="primary" data-room-action="create">모임방 만들기 ↗</button></section><section class="room-entry-card"><span class="room-eyebrow">JOIN WITH A NICKNAME</span><h3>초대받았나요?</h3><p>로그인 없이 닉네임과 방 코드만 있으면 돼요.</p><label>모임방 코드<input id="room-code" class="field" inputmode="numeric" maxlength="6" placeholder="6자리 숫자" value="${esc(code)}"></label><label>참여 닉네임<input id="room-join-name" class="field" maxlength="20" placeholder="함께 부를 이름"></label><button class="secondary" data-room-action="join">이 모임에 참여하기 ↗</button></section></div><div class="room-network-note"><b>같은 모임방에서 함께 메뉴를 선택할 수 있어요.</b><p>${esc(network?.phoneNote||'서버와 연결한 뒤 참여할 수 있어요.')} Windows 방화벽·공유기의 기기 간 연결 정책에 따라 접속 허용이 필요할 수 있어요.</p><small>방은 24시간 후 만료 · 최대 12명 · 개인 선택은 본인에게만 표시</small></div></div>`;bind();}
function renderInviteEntry(){
 document.documentElement.classList.add('room-invite-page');
 container.innerHTML=`<div class="room-app room-invite-entry">${intro(0)}<section class="room-entry-card"><span class="room-eyebrow">YOU ARE INVITED</span><h3>점심 모임에 초대됐어요!</h3><p>닉네임을 입력하면 이 모임방에 참여할 수 있어요.</p><label>초대받은 모임방<input id="room-code" class="field" readonly value="${esc(code)}" aria-label="모임방 코드"></label><label>참여 닉네임<input id="room-join-name" class="field" maxlength="20" autocomplete="nickname" enterkeyhint="go" placeholder="함께 부를 이름"></label><button class="primary" data-room-action="join">모임방 참여하기 ↗</button><p class="room-hint">로그인 없이 참여 · 최대 12명 · 방장이 시작하면 메뉴를 골라요.</p></section><button class="text-btn" data-room-action="entry">다른 방 만들기·참여하기</button></div>`;
 bind();container.querySelector('#room-join-name').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();container.querySelector('[data-room-action="join"]').click();}};
}
function filterChips(f){return `<span>⌖ ${esc(f.location)}</span><span>${Number(f.budget).toLocaleString()}원 이하</span><span>직선 ${f.distance}m</span><span>점심 ${Number.isFinite(f.lunchDeadline)?Math.max(0,Math.ceil((f.lunchDeadline-Date.now())/60000)):f.time}분</span><span>${esc(f.categories?.[0]||'전체')}</span>`;}
function members(){return `<div class="room-member-list">${room.members.map(m=>`<div class="room-member"><span class="room-avatar">${esc(m.nickname.slice(0,1))}</span><strong>${esc(m.nickname)} ${m.isHost?'♛':''}</strong><small>${room.phase==='lobby'?'참여 중':m.submitted?'선택 완료':'선택 중'}</small>${room.me.isHost&&room.phase==='lobby'&&!m.isHost?`<button class="text-btn" data-room-action="remove" data-id="${esc(m.id)}" aria-label="${esc(m.nickname)} 참여 취소">제외</button>`:''}</div>`).join('')}</div>`;}
function render(){if(!container||!room)return;const phase=room.phase;let body='';
 if(phase==='lobby'){const invite=`${network.publicUrl}/?room=${room.code}`;body=`<div class="room-lobby-grid"><section><span class="room-eyebrow">${room.me.isHost?'YOU ARE THE HOST':'WELCOME TO OUR TABLE'}</span><h3>${esc(room.title)}</h3><p>QR을 찍고 점심 모임에 참여하세요.</p><div class="room-invite"><img src="${appBase}/api/rooms/${room.code}/qr.svg" alt="같은 Wi-Fi에서 참여할 수 있는 초대 QR 코드" width="180" height="180"><div><small>모임방 코드</small><strong class="room-code-value">LUNCH ${room.code}</strong><button class="secondary" data-room-action="copy">초대 링크 복사</button></div></div><label class="room-link-label">휴대폰 초대 주소<input class="field" readonly value="${esc(invite)}" aria-label="휴대폰 초대 주소"></label><p class="room-hint">같은 Wi-Fi에서 접속하세요. 127.0.0.1 주소는 다른 휴대폰에서 열리지 않아요.</p><div class="room-filter-chips">${filterChips(room.filters)}</div></section><section class="room-roster"><div class="room-section-heading"><h3>참여자</h3><span>${room.total}/12명</span></div>${members()}${room.me.isHost?`<button class="primary" data-room-action="start" ${room.total<2?'disabled':''}>${room.total}명과 시작하기 ↗</button><p class="room-hint">시작하면 참여 인원과 메뉴 후보가 고정돼요.</p>`:'<p class="room-waiting">방장이 시작하면 메뉴를 고를 수 있어요.</p>'}<button class="text-btn" data-room-action="entry">다른 방 만들기·참여하기</button></section></div>`;}
 else if(phase==='voting'){body=`<div class="room-vote-heading"><span class="room-code-pill">LUNCH ${room.code} · ${esc(room.me.nickname)}</span><h3>오늘 먹고 싶은 메뉴는?</h3><p>${room.me.submitted?'선택을 제출했어요. 나머지 친구들을 기다려주세요.':'먹고 싶은 메뉴를 여러 개 골라주세요.'}</p></div><div class="room-menu-grid">${room.menus.map(m=>`<button class="room-menu-card ${draft.has(m.id)?'selected':''}" data-menu-id="${esc(m.id)}" aria-pressed="${draft.has(m.id)}" ${room.me.submitted?'disabled':''}><div class="room-menu-art"><span>${m.emoji}</span><i>${draft.has(m.id)?'✓':''}</i><small>메뉴 이미지 예시</small></div><strong>${esc(m.name)}</strong><span class="room-menu-category">${esc(m.category)} · ${m.price_verified?Number(m.verified_price).toLocaleString()+'원 확인':m.price_hint!=null?'기준 '+Number(m.price_hint).toLocaleString()+'원':'가격 미확인'}</span></button>`).join('')}</div><p class="room-private-note">🔒 내 선택은 다른 사람에게 보이지 않아요. 모두 제출하면 합계만 공개돼요.</p><button class="primary room-submit" data-room-action="submit" ${room.me.submitted||!draft.size?'disabled':''}>${room.me.submitted?'선택 제출 완료':'선택 완료 · '+draft.size+'개'} ↗</button><div class="room-progress"><span>${room.completed} / ${room.total}명 선택 완료</span><progress value="${room.completed}" max="${room.total}"></progress></div>${members()}${room.me.isHost?'<button class="text-btn" data-room-action="reset">대기실로 돌아가 참여자 다시 정리</button>':''}`;}
 else {const result=room.result,common=room.menus.filter(m=>result.commonIds.includes(m.id)),top=room.menus.filter(m=>result.topIds.includes(m.id)),selected=room.menus.find(m=>m.id===room.selectedId);body=`<div class="room-result-heading"><span class="room-code-pill">LUNCH ${room.code} · ROUND ${room.round}</span><h3>${phase==='decided'?'우리의 점심이 정해졌어요!':common.length?'우리 모두 좋아하는 메뉴':'아직 모두의 교집합은 없어요'}</h3><p>${phase==='decided'?'모두가 고른 후보에서 최종 메뉴를 결정했어요.':common.length?`${room.total}명 모두 선택한 메뉴가 ${common.length}개예요.`:`가장 많은 ${result.maxVotes}명이 선택한 후보부터 다시 골라볼까요?`}</p></div><div class="room-result-list">${(selected?[selected]:common.length?common:top).map(m=>`<article class="room-result-card"><span class="room-result-art">${m.emoji}</span><div><h4>${esc(m.name)}</h4><span class="room-vote-badge">${result.counts[m.id]}명 ${common.length?'모두 좋아요!':'선택'}</span></div></article>`).join('')}</div>${phase==='drawing'?'<div class="room-live-draw" role="status">룰렛이 돌아가고 있어요. 모두에게 같은 결과가 표시돼요.</div>':''}${phase==='decided'?`<button class="primary room-submit" data-room-action="restaurants">${esc(selected?.name)} 식당 찾기 ↗</button>`:phase==='results'&&room.me.isHost?(common.length?`<button class="primary room-submit" data-room-action="draw">${common.length>1?common.length+'개 메뉴로 룰렛 돌리기':'이 메뉴로 결정하기'} ↗</button>`:'<button class="primary room-submit" data-room-action="revote">최다 선택 후보로 다시 고르기 ↗</button>'):phase==='results'?'<p class="room-waiting">방장이 다음 단계를 선택하고 있어요.</p>':''}${room.me.isHost&&phase!=='drawing'?'<button class="secondary room-submit" data-room-action="reset">메뉴 다시 고르기 · 대기실로</button>':''}<div class="room-wheel ${phase==='drawing'&&!drawTarget?'is-waiting':''}" id="room-wheel" ${phase==='drawing'&&common.length>1?'':'hidden'}>${wheelSvg(common)}</div><p class="room-hint">백엔드 메뉴 후보·예산·거리 조건을 공유해요. 식당 탐색은 최종 메뉴를 확정한 뒤 연결됩니다.</p>`;}
 container.innerHTML=`<div class="room-app">${intro(phase==='lobby'?0:phase==='voting'?1:2)}${body}</div>`;bind();if(phase==='drawing'&&drawTarget)animateWheel();}
function wheelSvg(menus){if(!menus.length)return '';const n=menus.length,colors=['#FF641B','#263A57','#C5FF24','#8CACC8'];return `<span class="room-wheel-pointer">▼</span><svg viewBox="0 0 320 320" aria-label="공통 메뉴 룰렛">${menus.map((m,i)=>{const a=i/n*Math.PI*2-Math.PI/2,b=(i+1)/n*Math.PI*2-Math.PI/2,mid=(a+b)/2;return `<path d="M160 160 L${160+147*Math.cos(a)} ${160+147*Math.sin(a)} A147 147 0 ${n===1?1:0} 1 ${160+147*Math.cos(b)} ${160+147*Math.sin(b)} Z" fill="${colors[i%4]}" stroke="white" stroke-width="3"/><text x="${160+92*Math.cos(mid)}" y="${160+92*Math.sin(mid)}" fill="${i%4===2?'#17243B':'white'}" text-anchor="middle" dominant-baseline="central" font-size="12">${esc(m.name.slice(0,8))}</text>`;}).join('')}<circle cx="160" cy="160" r="29" fill="white"/><text x="160" y="164" text-anchor="middle" font-size="12" fill="#17243B">LUNCH</text></svg>`;}
function animateWheel(){const e=container?.querySelector('.room-wheel svg');if(!e||drawStarted)return;const ids=room.result.commonIds,i=ids.indexOf(drawTarget);if(i<0)return;drawStarted=true;e.getBoundingClientRect();e.style.transition='transform 2.5s cubic-bezier(.1,.7,.1,1)';e.style.transform=`rotate(${360*5+360-(i+.5)*360/ids.length}deg)`;}
function bind(){container.onclick=async e=>{const m=e.target.closest('[data-menu-id]');if(m&&room?.phase==='voting'&&!room.me.submitted&&!busy){const id=m.dataset.menuId;if(draft.has(id))draft.delete(id);else draft.add(id);render();return;}const b=e.target.closest('[data-room-action]');if(!b||b.disabled||busy)return;const action=b.dataset.roomAction;busy=true;b.disabled=true;try{
 if(action==='create'){const result=await api('/api/rooms',{nickname:container.querySelector('#room-host-name').value,title:container.querySelector('#room-title').value,filters:callbacks.getFilters()});await enter(result);}
 else if(action==='join'){const c=container.querySelector('#room-code').value.trim();if(!/^\d{6}$/.test(c))throw Error('6자리 방 코드를 확인해주세요.');const result=await api('/api/rooms/'+c+'/join',{nickname:container.querySelector('#room-join-name').value});await enter(result);}
 else if(action==='copy'){const text=`${network.publicUrl}/?room=${room.code}`;try{await navigator.clipboard.writeText(text);notice('초대 링크를 복사했어요.');}catch{notice('아래 초대 주소를 길게 누르거나 선택해 복사해주세요.');container.querySelector('.room-link-label input')?.select();}}
 else if(action==='entry'){generation++;clearTimeout(timer);const url=new URL(location.href);url.searchParams.delete('room');history.replaceState(null,'',url);try{sessionStorage.removeItem('lunchrun3-last-room');}catch{}code='';key='';draft.clear();renderEntry();}
 else if(action==='restaurants'){const selected=room.menus.find(m=>m.id===room.selectedId);if(!selected)throw Error('최종 메뉴를 확인해주세요.');const filters=room.filters,total=room.total,choose=callbacks.onChoose;closeRoomFlow();await choose(selected,filters,total);}
 else{const data={round:room.round,...(action==='submit'?{choices:[...draft]}:{}),...(action==='remove'?{id:b.dataset.id}:{})};const result=await api('/api/rooms/'+code+'/'+(action==='submit'?'select':action),data);if(action==='draw'){drawTarget=result.targetId;drawStarted=false;}await refresh(true);}
 }catch(error){notice(error.message);}finally{busy=false;if(b.isConnected)b.disabled=false;}};}
async function enter(value){code=value.code;key=value.token;const url=new URL(location.href);url.searchParams.set('room',code);history.replaceState(null,'',url);saveToken(code,key);room=await api('/api/rooms/'+code);draft=new Set(room.me.choices);signature='';drawTarget=null;drawStarted=false;lockSharedFilters(true);render();poll();}
async function refresh(force=false){if(!container||!code||!key)return;const gen=generation;const next=await api('/api/rooms/'+code);const latestNetwork=next.phase==='lobby'?await api('/api/network'):network;if(gen!==generation||!container)return;if(room?.round!==next.round){draft=new Set(next.me.choices);drawTarget=null;drawStarted=false;}if(latestNetwork?.publicUrl!==network?.publicUrl)force=true;if(JSON.stringify([room?.filters,room?.total])!==JSON.stringify([next.filters,next.total]))callbacks.onContext?.(next.filters,next.total,next.menus);network=latestNetwork;room=next;const sig=JSON.stringify(next);if(force||sig!==signature){signature=sig;render();}}
function poll(){clearTimeout(timer);const gen=generation;timer=setTimeout(async()=>{try{if(!busy)await refresh();}catch(e){notice('연결이 잠시 끊겼어요. '+e.message);}if(container&&gen===generation)poll();},1100);}
